// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    PENNY_BY_PENNY c;
    function setUp() public { c = new PENNY_BY_PENNY(); }

    function testFuzz_property(address caller, uint256 val) public {
        vm.assume(caller != address(0));

        vm.deal(caller, 1 ether);

        vm.prank(caller);
        bool ok;
        try c.SetMinSum(val) {
            ok = true;
        } catch {
            ok = false;
        }

        if (ok) {
            assertTrue(c.MinSum() == val);
        } else {
            assertTrue(c.MinSum() != val);
        }
    }
}
